    /**
     * Method to retrieve the Alert via an AlertPrimaryKey.
     * @param 	id Long
     * @return 	Alert
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Alert handle( FindAlertQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getAlertId() );
    }
    
    /**
     * Method to retrieve a collection of all Alerts
     *
     * @param	query	FindAllAlertQuery 
     * @return 	List<Alert> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Alert> handle( FindAllAlertQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindAlert,
 * but only if the id matches
 *
 * @param		entity	Alert
 */
	protected void emitFindAlert( Alert entity ) {
		LOGGER.info("handling emitFindAlert" );
		
	    queryUpdateEmitter.emit(FindAlertQuery.class,
	                            query -> query.getFilter().getAlertId().equals(entity.getAlertId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllAlert
	 * 
	 * @param		entity	Alert
	 */
	protected void emitFindAllAlert( Alert entity ) {
		LOGGER.info("handling emitFindAllAlert" );
		
	    queryUpdateEmitter.emit(FindAllAlertQuery.class,
	                            query -> true,
	                            entity);
	}

